@js:
function login() {
	let une = source.getLoginInfoMap().get("账号")
	let pwd = source.getLoginInfoMap().get("密码")

	if (une && pwd) {
		let body = JSON.stringify({
			"is_encrypted": 0,
			"platform": "pc",
			"client": "web",
			"sign": "",
			"gz": 0,
			"d": {
				"username": String(une),
				"password": String(pwd)
			}
		})
		let url = source.bookSourceUrl + 'proxy/api/user/login'
		let ck = java.post(url, body, { "Content-Type": "application/json","user-agent":"Dart/2.10 (dart:io)" }).cookies()

		let header = JSON.stringify({
			"Cookie": String(ck).match(/\{(.*?)\}/)[1].replace(/,/g, ';')
		})
		source.putLoginHeader(header)
	}
}

